/// Mirrors the web: parse a curriculumPath segment ("board.class.…").
({String board, int? cls})? _parsePath(String path){
  final parts = path.split('.');
  if(parts.length < 2) return null;
  final cls = int.tryParse(parts[1]);
  return (board: parts[0].toLowerCase(), cls: cls);
}

/// NEET UG is CBSE Class 11+12 Physics/Chemistry/Biology. Only 3 concepts are
/// tagged `neet.ug.*`, so those two classes act as the fallback. Keep in sync
/// with NEET_FALLBACK_CLASSES in js/learning/arena-curriculum.js.
const _neetFallbackClasses = [11, 12];
const _neetSubjects = {'Physics', 'Chemistry', 'Biology'};

List<String> getSubjectsForTrack(String trackId, int? classNum){
  final t = trackId.toLowerCase();
  if(t=='jee') return ['Physics','Chemistry','Mathematics'];
  if(t=='neet') return ['Physics','Chemistry','Biology'];
  if(t=='maharashtra' || t=='cbse'){
    // Derive from the data, exactly like the web. The previous hardcoded lists
    // were wrong for 6 of 8 board/class combos and produced subject cards that
    // rendered zero chapters.
    final seen = <String>{};
    for(final c in _seedChapters){
      for(final p in c.curriculumPaths){
        final parsed = _parsePath(p);
        if(parsed != null && parsed.board == t && parsed.cls == classNum) seen.add(c.subject);
      }
    }
    if(seen.isEmpty) return [];
    const mh9Order = [
      'Science & Technology - Part 1','Science & Technology - Part 2',
      'Mathematics - Part 1','Mathematics - Part 2',
      'History','Political Science','Geography',
    ];
    if(t=='maharashtra' && classNum == 9){
      final ordered = mh9Order.where(seen.contains).toList();
      for(final s in seen){ if(!ordered.contains(s)) ordered.add(s); }
      return ordered;
    }
    final order = ['Physics','Chemistry','Biology','Mathematics','Science', ...mh9Order];
    final list = seen.toList()..sort((a,b){
      final ia = order.indexOf(a), ib = order.indexOf(b);
      if(ia == -1 && ib == -1) return a.compareTo(b);
      if(ia == -1) return 1;
      if(ib == -1) return -1;
      return ia - ib;
    });
    return list;
  }
  return [];
}

List<Chapter> getChapters(String trackId, String subject, int? classNum){
  final t = trackId.toLowerCase();
  // Exact subject match, then scope by track the same way the web does.
  // Previously this matched subject only, so every board/class pulled chapters
  // from all other boards, and `maharashtra` classes 10-12 were forced empty.
  final filtered = _seedChapters.where((c){
    if(c.subject != subject) return false;
    if(t == 'jee') return c.curriculumPaths.any((p) => p.startsWith('jee.'));
    if(t == 'neet'){
      if(c.curriculumPaths.any((p) => p.startsWith('neet.'))) return true;
      if(!_neetSubjects.contains(c.subject)) return false;
      return c.curriculumPaths.any((p){
        final parsed = _parsePath(p);
        return parsed != null && parsed.board == 'cbse' && _neetFallbackClasses.contains(parsed.cls);
      });
    }
    if(t == 'maharashtra' || t == 'cbse'){
      if(classNum == null) return false;
      return c.curriculumPaths.any((p){
        final parsed = _parsePath(p);
        return parsed != null && parsed.board == t && parsed.cls == classNum;
      });
    }
    return false;
  }).toList();
  // Topo sort by prerequisites (same Kahn as web)
  final idToChapter = {for(var c in filtered) c.conceptId: c};
  final indeg=<String,int>{}; final adj=<String, List<String>>{};
  for(var c in filtered){ indeg[c.conceptId]=0; adj[c.conceptId]=[]; }
  for(var c in filtered){
    for(var pre in c.prerequisites){
      if(idToChapter.containsKey(pre)){
        adj[pre]!.add(c.conceptId);
        indeg[c.conceptId]= indeg[c.conceptId]!+1;
      }
    }
  }
  final queue = filtered.where((c)=> indeg[c.conceptId]==0).toList()..sort((a,b)=> a.difficulty.compareTo(b.difficulty));
  // Start EMPTY. This accumulator used to be pre-seeded with a hardcoded copy of the
  // chapter list, which injected phantom chapters into every sorted result.
  final result=<Chapter>[];
  final visited=<String>{};
  while(queue.isNotEmpty){
    queue.sort((a,b)=> a.difficulty.compareTo(b.difficulty));
    final cur=queue.removeAt(0);
    result.add(cur); visited.add(cur.conceptId);
    for(var nxt in adj[cur.conceptId]!){
      indeg[nxt]=indeg[nxt]!-1;
      if(indeg[nxt]==0) queue.add(idToChapter[nxt]!);
    }
  }
  for(var c in filtered){ if(!visited.contains(c.conceptId)) result.add(c); }
  return result;
}

String toSubjectKey(String trackId, String subject, int? classNum){
  final t = trackId.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '_');
  final s = subject.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '_');
  if(t=='maharashtra' || t=='cbse'){
    return '${t}_${classNum ?? ''}_${s}'.replaceAll('__', '_');
  }
  return '${t}_$s';
}
